#!/usr/bin/env python3
"""Minimal VT100 screen emulator sufficient for FTXUI output replay."""
import sys, re

class Screen:
    def __init__(self, cols, rows):
        self.cols, self.rows = cols, rows
        self.buf = [[' '] * cols for _ in range(rows)]
        self.attrs = [[None] * cols for _ in range(rows)]
        self.cx = self.cy = 0
        self.cur_attr = []
        self.esc = ''

    def put(self, ch):
        if self.cx >= self.cols:
            self.cx = 0
            self.cy += 1
        if self.cy >= self.rows:
            self.scroll(1)
            self.cy = self.rows - 1
        if 0 <= self.cy < self.rows and 0 <= self.cx < self.cols:
            self.buf[self.cy][self.cx] = ch
            self.attrs[self.cy][self.cx] = list(self.cur_attr)
        self.cx += 1

    def scroll(self, n):
        for _ in range(n):
            self.buf.pop(0)
            self.buf.append([' '] * self.cols)
            self.attrs.pop(0)
            self.attrs.append([None] * self.cols)

    def feed(self, data: bytes):
        s = data.decode('utf-8', errors='replace')
        i = 0
        while i < len(s):
            ch = s[i]
            if self.esc is not None and self.esc != '':
                self.esc += ch
                if self.esc[-1].isalpha() or self.esc[-1] in '@`~hlqm':
                    self.handle_csi(self.esc)
                    self.esc = ''
                i += 1
                continue
            if ch == '\x1b':
                self.esc = ''
                self.esc = '\x1b'
                # wait for next
                self.esc_pending = True
                i += 1
                # consume introducer
                if i < len(s) and s[i] in '[(':
                    self.esc += s[i]
                    if s[i] == '(':
                        i += 2  # skip charset designator
                        self.esc = ''
                        continue
                    i += 1
                    self.esc = '['  # collecting params
                else:
                    # two-char escape like ESC=, ESC>
                    if i < len(s):
                        i += 1
                    self.esc = ''
                continue
            if self.esc == '[':
                self.esc += ch
                if ch.isalpha() or ch in '@`~':
                    self.handle_csi(self.esc)
                    self.esc = ''
                i += 1
                continue
            if ch == '\r':
                self.cx = 0
            elif ch == '\n':
                self.cy += 1
                if self.cy >= self.rows:
                    self.scroll(1)
                    self.cy = self.rows - 1
            elif ch == '\x08':
                self.cx = max(0, self.cx - 1)
            elif ch == '\x07':
                pass
            elif ch >= ' ' or ch == '\t':
                self.put(ch)
            i += 1

    def handle_csi(self, esc):
        m = re.match(r'\[([0-9;?]*)([A-Za-z@`~])$', esc)
        if not m:
            return
        params, cmd = m.group(1), m.group(2)
        nums = [int(x) if x else 0 for x in params.split(';')] if params else []
        def p(n, d=1):
            return nums[n] if n < len(nums) and nums[n] != 0 else d
        if cmd == 'A':
            self.cy = max(0, self.cy - p(0))
        elif cmd == 'B':
            self.cy = min(self.rows - 1, self.cy + p(0))
        elif cmd == 'C':
            self.cx = min(self.cols - 1, self.cx + p(0))
        elif cmd == 'D':
            self.cx = max(0, self.cx - p(0))
        elif cmd == 'E':
            self.cy = min(self.rows - 1, self.cy + p(0)); self.cx = 0
        elif cmd == 'F':
            self.cy = max(0, self.cy - p(0)); self.cx = 0
        elif cmd == 'G':
            self.cx = min(self.cols - 1, p(0) - 1)
        elif cmd in 'Hf':
            self.cy = min(self.rows - 1, p(0) - 1)
            self.cx = min(self.cols - 1, p(1) - 1)
        elif cmd == 'J':
            n = nums[0] if nums else 0
            if n == 2:
                self.buf = [[' '] * self.cols for _ in range(self.rows)]
                self.attrs = [[None] * self.cols for _ in range(self.rows)]
        elif cmd == 'K':
            n = nums[0] if nums else 0
            if n == 2 or n == 0:
                for x in range(self.cx if n == 0 else 0, self.cols):
                    self.buf[self.cy][x] = ' '
                    self.attrs[self.cy][x] = None
        elif cmd == 'm':
            self.cur_attr = nums if nums else [0]

    def render(self, with_attrs=False):
        out = []
        for i in range(self.rows):
            line = ''.join(self.buf[i])
            out.append(f"{i:02d}|{line}")
        return '\n'.join(out)

if __name__ == '__main__':
    path = sys.argv[1]
    cols = int(sys.argv[2]) if len(sys.argv) > 2 else 80
    rows = int(sys.argv[3]) if len(sys.argv) > 3 else 24
    data = open(path, 'rb').read()
    scr = Screen(cols, rows)
    scr.feed(data)
    print(scr.render())

